import sys
from collections import defaultdict

def main():
    input_data = sys.stdin.read().split()
    idx = 0

    if idx >= len(input_data):
        return

    n = int(input_data[idx])
    idx += 1
    e = int(input_data[idx])
    idx += 1

    A = []
    for _ in range(2 * e):
        if idx < len(input_data):
            A.append(int(input_data[idx]))
            idx += 1

    B = []
    for _ in range(2 * e):
        idx += 1
        if idx < len(input_data):
            B.append(int(input_data[idx]))
            idx += 1

    adjA = defaultdict(list)
    for i in range(0, 2 * e, 2):
        u = A[i]
        v = A[i+1]
        adjA[u].append(v)

    adjB = defaultdict(list)
    for i in range(0, 2*e, 2):
        u = B[i]
        v = B[i+1]
        adjB[u].append(v)

    def get_children(node, adj):
        return sorted(adj.get(node, []))

    def check_mirror(u, v):
        children_u = get_children(u, adjA)
        children_v = get_children(v, adjB)

        if len(children_u) != len(children_v):
            return False

        children_v_reversed = children_v[::-1]

        for i in range(len(children_u)):
            if not check_mirror(children_u[i], children_v_reversed[i]):
                return False

        return True

    root = 1
    if not check_mirror(root, root):
        print(0)
    else:
        print(1)

if __name__ == "__main__":
    main()
